#!/bin/bash
# Ева: выкатка правки отчётов (repair + повтор при отказе шлюза). Бэкап, проверка, автооткат.
set -e
D=/opt/eva-admin-reports; B=/root/eva-reports-backup-$(date +%Y%m%d-%H%M%S)
echo "== 1. бэкап в $B"; mkdir -p $B; cp -a $D/worker.py $D/semantic_core.py $B/
echo "== 2. сверка с репозиторием"; echo "1844caf11e3152a1cf110a4bf53a6fc8a29fadca5988ec75bcbf1ee9546a59df  $D/semantic_core.py" | sha256sum -c --quiet || { echo "ОШИБКА: semantic_core.py на сервере изменён, ничего не менял"; exit 1; }
echo "== 3. установка"
T=$(mktemp -d); cp $D/worker.py $D/semantic_core.py $T/
echo '' | base64 -d > $T/semantic_core.py
echo '' | base64 -d > $T/worker.patch
(cd $T && patch -p1 --dry-run < worker.patch >/dev/null && patch -p1 -s < worker.patch) || { echo "ОШИБКА: worker.py на сервере отличается, ничего не менял"; exit 1; }
python3 -m py_compile $T/worker.py $T/semantic_core.py
cp $T/semantic_core.py $T/worker.py $D/; rm -rf $D/__pycache__ $T
echo "== 4. перезапуск"
systemctl restart eva-admin-reports; sleep 8
if systemctl is-active --quiet eva-admin-reports; then echo "OK: eva-admin-reports работает"; else
  echo "СБОЙ, откат"; cp -a $B/worker.py $B/semantic_core.py $D/; systemctl restart eva-admin-reports; systemctl is-active eva-admin-reports; exit 1; fi
journalctl -u eva-admin-reports --since '-1 min' -p warning --no-pager | tail -5 | cut -c1-200
echo "== готово, бэкап: $B"
